//! Cargo-driven `d3dx10_42.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("d3dx10_42-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "import:d3dx10_43", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "x86_64" => &["engine:wine", "import:d3dx10_43", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        "aarch64" => &["engine:wine", "import:d3dx10_43", "import:msvcrt", "import:kernel32", "import:ntdll", "body", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/d3dx10_42",
        "dll/directx/wine/d3dx10_42",
        "sdk/include/wine",
        "@build/sdk/include/wine",
        "@std",
        "sdk/lib/pseh/include",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("d3dx10_42_shims", &["dll/directx/wine/d3dx10_42/d3dx10_42_main.c"])
        .rc("dll/directx/wine/d3dx10_42/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/d3dx10_42/d3dx10_42.spec", "d3dx10_42.dll")
        .spec_stubs()
        .import_lib("dll/directx/wine/d3dx10_43/d3dx10_43.spec", "d3dx10_43.dll", "d3dx10_43")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
